mapper.select:
/* ChkLst04Mapper.selectDefectList */ SELECT A.CMPNY_CD AS cmpnyCd , A.SITE_CD AS siteCd , S.SITE_NM AS siteNm , T.CHKLST_TYPE AS chkLstType , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'BAIM_VAL', T.CHKLST_TYPE, 'COM001') AS chkLstTypeNm , A.CHKPT_CD AS chkptCd , T.CHKPT_NM AS chkptNm , A.INSPECT_ITEM_CD AS inspectItemCd , I.INSPECT_ITEM_SUBJ AS inspectItemSubj , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'USER_NM', A.INSERT_NO, NULL) AS inspectorNm , A.WORK_DATE AS workDate , A.ANSWER_DESC AS answerDesc , CONCAT(A.FILE_MGMT_CD, IFNULL(F.FILE_EXT, '')) AS fileMgmtCd , F.FILE_PATH AS filePath , D.ACTION_DESC AS actionDesc , CASE WHEN D.ACTION_DESC IS NOT NULL THEN 'Y' ELSE 'N' END AS actionStatus FROM TB_CHKPT_INSPECT_ANSWER A INNER JOIN TB_USER_SITE_AUTH AU ON ( A.CMPNY_CD = AU.CMPNY_CD AND A.SITE_CD = AU.SITE_CD AND AU.USER_CD = #{gvUserCd} ) INNER JOIN TB_SITE S ON ( A.CMPNY_CD = S.CMPNY_CD AND A.SITE_CD = S.SITE_CD ) INNER JOIN TB_CHKPT_TYPE_MGMT T ON ( A.CMPNY_CD = T.CMPNY_CD AND A.SITE_CD = T.SITE_CD AND A.CHKPT_CD = T.CHKPT_CD ) INNER JOIN TB_CHKPT_INSPECT_ITEM I ON ( A.CMPNY_CD = I.CMPNY_CD AND T.CHKLST_TYPE = I.CHKLST_TYPE AND A.INSPECT_ITEM_CD = I.INSPECT_ITEM_CD ) LEFT JOIN TB_FILE_INFO F ON ( A.CMPNY_CD = F.CMPNY_CD AND A.FILE_MGMT_CD = F.FILE_MGMT_CD AND F.FILE_TYPE = #{fileType} ) LEFT JOIN TB_CHKPT_DEFECT_ACTION D ON ( A.CMPNY_CD = D.CMPNY_CD AND A.SITE_CD = D.SITE_CD AND A.CHKPT_CD = D.CHKPT_CD AND A.INSPECT_ITEM_CD = D.INSPECT_ITEM_CD AND A.WORK_DATE = D.WORK_DATE ) WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd} AND A.INSPECT_ANSWER_TYPE = 'N'
AND A.SITE_CD = #{siteCd}
AND T.CHKLST_TYPE = #{chkLstType}
AND A.CHKPT_CD = #{chkptCd}
AND A.INSPECT_ITEM_CD = #{inspectItemCd}
AND D.ACTION_DESC IS NOT NULL
AND D.ACTION_DESC IS NULL
ORDER BY A.WORK_DATE DESC, A.SITE_CD, A.CHKPT_CD, A.INSPECT_ITEM_CD

/* ChkLst04Mapper.selectChkptTargetList */
SELECT
      A.CHKPT_CD                AS chkptCd
    , A.CHKPT_NM                AS chkptNm
    , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'USER_NM', A.MGMT_USER_CD, NULL) AS mgmtUserNm
    , A.USE_YN                  AS useYn
    , A.CHKPT_DESC              AS chkptDesc
FROM TB_CHKPT_TYPE_MGMT A
     INNER JOIN TB_USER_SITE_AUTH AU
        ON (
            A.CMPNY_CD = AU.CMPNY_CD
        AND A.SITE_CD = AU.SITE_CD
        AND AU.USER_CD = #{gvUserCd}
        )
WHERE 1=1
  AND A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.CHKLST_TYPE = #{chkLstType}


    AND A.USE_YN = #{useYn}


    AND A.CHKPT_NM LIKE CONCAT('%', #{chkptNm}, '%')

ORDER BY A.CHKPT_NM

/* ChkLst04Mapper.selectInspectItemList */
SELECT
      A.INSPECT_ITEM_CD         AS inspectItemCd
    , A.INSPECT_ITEM_SUBJ       AS inspectItemSubj
    , A.STR_DATE                AS strDate
    , A.USE_YN                  AS useYn
FROM TB_CHKPT_INSPECT_ITEM A
WHERE 1=1
  AND A.CMPNY_CD = #{gvCmpnyCd}
  AND A.CHKLST_TYPE = #{chkLstType}


    AND A.USE_YN = #{useYn}


    AND A.INSPECT_ITEM_SUBJ LIKE CONCAT('%', #{inspectItemSubj}, '%')

ORDER BY A.SORT_IDX, A.INSPECT_ITEM_CD

/* ChkLst04Mapper.countDefectInScope */
SELECT COUNT(1)
FROM TB_CHKPT_INSPECT_ANSWER A
     INNER JOIN TB_USER_SITE_AUTH AU
        ON (
            A.CMPNY_CD = AU.CMPNY_CD
        AND A.SITE_CD = AU.SITE_CD
        AND AU.USER_CD = #{gvUserCd}
        )
WHERE 1=1
  AND A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.CHKPT_CD = #{chkptCd}
  AND A.INSPECT_ITEM_CD = #{inspectItemCd}
  AND A.WORK_DATE = #{workDate}
  AND A.INSPECT_ANSWER_TYPE = 'N'

mapper.insert:
/* ChkLst04Mapper.saveDefectAction */
INSERT INTO TB_CHKPT_DEFECT_ACTION (
      CMPNY_CD
    , SITE_CD
    , CHKPT_CD
    , INSPECT_ITEM_CD
    , WORK_DATE
    , ACTION_DESC
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
      #{gvCmpnyCd}
    , #{siteCd}
    , #{chkptCd}
    , #{inspectItemCd}
    , #{workDate}
    , #{actionDesc}
    , #{gvUserCd}
    , NOW()
    , NULL
    , NULL
) AS NEW
ON DUPLICATE KEY UPDATE
      ACTION_DESC = NEW.ACTION_DESC
    , UPDATE_NO   = #{gvUserCd}
    , UPDATE_DATE = NOW()
